#include <bits/stdc++.h>
using namespace std;

void solve() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;
    const int MAXA = 200000;

    vector<int> a(n + 1);                   // 1‑based 序列
    for (int i = 1; i <= n; ++i) cin >> a[i];

    // 预处理每个数的所有因子：整除筛
    vector<vector<int>> divisors(MAXA + 1);
    for (int d = 1; d <= MAXA; ++d) {
        for (int m = d; m <= MAXA; m += d) {
            divisors[m].push_back(d);
        }
    }

    // cntMul[d] ：能被 d 整除的元素个数
    vector<int> cntMul(MAXA + 1, 0);
    for (int i = 1; i <= n; ++i) {
        for (int d : divisors[a[i]]) cntMul[d]++;
    }

    // 处理操作
    for (int i = 0; i < q; ++i) {
        int t; cin >> t;
        if (t == 1) {                         // 询问操作
            int k; cin >> k;
            cout << cntMul[k] << '\n';
        } else {                              // 更新操作
            int idx, x; cin >> idx >> x;
            int old = a[idx];
            if (old != x) {
                // 移除旧值贡献
                for (int d : divisors[old]) cntMul[d]--;
                // 添加新值贡献
                for (int d : divisors[x]) cntMul[d]++;
                a[idx] = x;
            }
        }
    }
}

int main() {
    solve();
    return 0;
}
